.gmw-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.gmw-root,.gmw-root *,.gmw-root *::before,.gmw-root *::after{box-sizing:border-box}
.gmw-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.gmw-root img{display:block;border:0;max-width:none}
.gmw-root > [data-node-id]{will-change:transform}
.gmw-root [hidden]{display:none!important}
.gmw-root [data-sh-theme="light"]{display:none!important}
.gmw-root[data-theme="light"] [data-sh-theme="light"]{display:block!important}
.gmw-root[data-theme="light"] [data-sh-theme="dark"]{display:none!important}
